// Test-only exact inverse. Preserve all other current code and historical evidence.
import assert from 'node:assert/strict';
import { cpSync, mkdirSync, mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { restorePreA2Files } from './a2DressControlHistoricalReplay.mjs';
export const A1_BASE_COMMIT = 'ffb2e91e61787159d7dbc724dc0129e87537dfcb';
export const A1_ROOT = fileURLToPath(new URL('../../', import.meta.url));
export const A1_BEFORE = `? structuredIdentityLines
      : [groupLine('Identity and body', groups.identityAndBody)]`;
export const A1_AFTER = `? [
          ensureTerminalPeriod(cleanCharacterProfileGroupText(groups.identityAndBody)
            .match(/^a\\s+20-year-old\\s+adult\\s+[^,]*?\\bwoman\\b/i)?.[0] || ''),
          ...structuredIdentityLines,
        ]
      : [groupLine('Identity and body', groups.identityAndBody)]`;
export function preA1EngineSource(source) {
  assert.equal(source.split(A1_AFTER).length - 1, 2, 'A1 inverse requires both exact reviewed insertions');
  assert.equal(source.includes(A1_BEFORE), false, 'A1 inverse rejects mixed or duplicated branches');
  return source.replaceAll(A1_AFTER, A1_BEFORE);
}
export function openPreA1ReplayRoot() {
  const directory = mkdtempSync(join(tmpdir(), 'vps-a1-history-'));
  try {
    mkdirSync(join(directory, 'webapp'));
    for (const path of ['webapp/src', 'scripts', 'knowledge_base']) cpSync(join(A1_ROOT, path), join(directory, path), { recursive: true });
    for (const file of ['package.json', 'package-lock.json']) cpSync(join(A1_ROOT, 'webapp', file), join(directory, 'webapp', file));
    symlinkSync(join(A1_ROOT, 'webapp/node_modules'), join(directory, 'webapp/node_modules'), 'dir');
    restorePreA2Files(directory);
    const file = join(directory, 'webapp/src/lib/engine.js');
    writeFileSync(file, preA1EngineSource(readFileSync(file, 'utf8')));
    return { directory, cleanup: () => rmSync(directory, { recursive: true, force: true }) };
  } catch (error) { rmSync(directory, { recursive: true, force: true }); throw error; }
}
export async function withPreA1ReplayRoot(run) {
  const { directory, cleanup } = openPreA1ReplayRoot();
  try { return await run(directory); } finally { cleanup(); }
}
export async function withPreAllA5ReplayRoot(run) {
  return withPreA1ReplayRoot(async directory => {
    const historical = await import(pathToFileURL(join(directory, 'scripts/lib/a5XimendingHistoricalReplay.mjs')).href);
    return historical.withPreAllA5ReplayRoot(run);
  });
}

// Test-only exact data inverse. No public renderer or historical seal is rewritten.
import assert from 'node:assert/strict';
import { preA2OutfitDatabase, restorePreA2OutfitFiles } from './a2OutfitControlHistoricalReplay.mjs';
import { execFileSync } from 'node:child_process';
import { cpSync, mkdirSync, mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';
import { isDeepStrictEqual } from 'node:util';
export const A2_ROOT = fileURLToPath(new URL('../../', import.meta.url));
export const A2_REVIEW = JSON.parse(readFileSync(new URL('./a2DressControlReview.json', import.meta.url)));
// Separately reviewed main integration; the original prompt oracle remains at A2_REVIEW.baseCommit.
export const A2_INTEGRATION_COMMIT = 'e9983769e326ead175b381834c6e2df4fd02e28d';
export const A2_VIDEO_PATHS = Object.freeze([
  'webapp/src/App.jsx',
  'webapp/src/components/VideoWorkspace.jsx',
  'webapp/src/lib/comfyVideoClient.js',
  'webapp/src/lib/videoWorkspaceController.js',
  'webapp/src/main.jsx',
  'webapp/src/styles/videoWorkspace.css',
]);
export function preVideoSources(current, before, after) {
  const states = A2_VIDEO_PATHS.map(path => {
    assert.equal(typeof before[path], 'string', 'A2 video inverse requires old source: ' + path);
    assert.equal(typeof after[path], 'string', 'A2 video inverse requires reviewed source: ' + path);
    assert.notEqual(before[path], after[path], 'A2 video inverse requires a changed source: ' + path);
    const state = current[path] === before[path] ? 'before' : current[path] === after[path] ? 'after' : 'unknown';
    assert.notEqual(state, 'unknown', 'A2 video inverse rejects unreviewed source: ' + path);
    return state;
  });
  assert.equal(new Set(states).size, 1, 'A2 video inverse rejects mixed states');
  return Object.fromEntries(A2_VIDEO_PATHS.map(path => [path, before[path]]));
}
function restorePreVideoFiles(directory) {
  const fromGit = commit => Object.fromEntries(A2_VIDEO_PATHS.map(path => [path,
    execFileSync('git', ['-C', A2_ROOT, 'show', commit + ':' + path], { encoding: 'utf8' }),
  ]));
  const current = Object.fromEntries(A2_VIDEO_PATHS.map(path => [path, readFileSync(join(directory, path), 'utf8')]));
  // Validate all six exact sources before writing anything in the isolated replay copy.
  const restored = preVideoSources(current, fromGit(A2_REVIEW.baseCommit), fromGit(A2_INTEGRATION_COMMIT));
  for (const [path, source] of Object.entries(restored)) writeFileSync(join(directory, path), source);
}

function inverse(rows, key, beforeKey, afterKey) {
  const matches = A2_REVIEW.rows.map(r => {
    const indices = rows.flatMap((x, i) => x[key] === r.id ? [i] : []);
    assert.equal(indices.length, 1, 'A2 inverse requires exactly one issued ID: ' + r.id);
    const index = indices[0], value = rows[index];
    const state = isDeepStrictEqual(value, r[afterKey]) ? 'after' : isDeepStrictEqual(value, r[beforeKey]) ? 'before' : 'unknown';
    assert.notEqual(state, 'unknown', 'A2 inverse rejects changed text, aliases or metadata: ' + r.id);
    return { index, state, r };
  });
  assert.equal(new Set(matches.map(x => x.state)).size, 1, 'A2 inverse rejects mixed migration states');
  for (const { index, r } of matches) rows[index] = structuredClone(r[beforeKey]);
  return matches[0].state;
}
export function preA2Database(database) {
  const copy = preA2OutfitDatabase(database);
  inverse(copy.Wardrobe['連身 (Dresses)'], 'stableId', 'generatedBefore', 'generatedAfter');
  return copy;
}
export function restorePreA2Files(directory) {
  restorePreA2OutfitFiles(directory);
  const categoryFile = join(directory, A2_REVIEW.sourceFile);
  const category = JSON.parse(readFileSync(categoryFile));
  const state = inverse(category.entries, 'id', 'before', 'after');
  const databaseFile = join(directory, 'webapp/src/data/database.json');
  const database = JSON.parse(readFileSync(databaseFile));
  const databaseState = inverse(database.Wardrobe['連身 (Dresses)'], 'stableId', 'generatedBefore', 'generatedAfter');
  assert.equal(state, databaseState, 'A2 category and generated data must agree');
  const markdownFile = join(directory, 'knowledge_base/wardrobe_and_styling.md');
  let markdown = readFileSync(markdownFile, 'utf8');
  for (const row of A2_REVIEW.rows) {
    const from = '| `' + row[state === 'after' ? 'after' : 'before'].en + '` |';
    assert.equal(markdown.split(from).length - 1, 1, 'A2 Markdown row must agree: ' + row.id);
    if (state === 'after') markdown = markdown.replace(from, '| `' + row.before.en + '` |');
  }
  writeFileSync(categoryFile, JSON.stringify(category, null, 2) + '\n');
  writeFileSync(databaseFile, JSON.stringify(database, null, 2) + '\n');
  writeFileSync(markdownFile, markdown);
  restorePreVideoFiles(directory);
}
export function openPreA2ReplayRoot() {
  const directory = mkdtempSync(join(tmpdir(), 'vps-a2-dresses-history-'));
  try {
    mkdirSync(join(directory, 'webapp'));
    for (const path of ['webapp/src', 'scripts', 'knowledge_base']) cpSync(join(A2_ROOT, path), join(directory, path), { recursive: true });
    for (const file of ['package.json', 'package-lock.json']) cpSync(join(A2_ROOT, 'webapp', file), join(directory, 'webapp', file));
    symlinkSync(join(A2_ROOT, 'webapp/node_modules'), join(directory, 'webapp/node_modules'), 'dir');
    restorePreA2Files(directory);
    return { directory, cleanup: () => rmSync(directory, { recursive: true, force: true }) };
  } catch (error) { rmSync(directory, { recursive: true, force: true }); throw error; }
}
export async function withPreA2ReplayRoot(run) {
  const { directory, cleanup } = openPreA2ReplayRoot();
  try { return await run(directory); } finally { cleanup(); }
}

import { preA2SpecialTapeDatabase, preA2SpecialTapeManagementSources, restorePreA2SpecialTapeFiles } from './a2SpecialTapeReplay.mjs';
import { restorePreA2WardrobeRecoveryFiles } from './a2WardrobeColorRecoveryReplay.mjs';
// Test-only inverse; validate the whole reviewed state before writing an isolated replay.
import assert from 'node:assert/strict';
import { cpSync, existsSync, mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';
import { isDeepStrictEqual } from 'node:util';
import { createHash } from 'node:crypto';
export const A2_OUTFIT_ROOT = fileURLToPath(new URL('../../', import.meta.url));
export const A2_OUTFIT_REVIEW = JSON.parse(readFileSync(new URL('./a2OutfitControlReview.json', import.meta.url)));
const patches = JSON.parse(readFileSync(new URL('./a2OutfitControlPatches.json', import.meta.url)));
const hash = text => createHash('sha256').update(text).digest('hex');
function inverse(rows, key, beforeKey, afterKey) {
  assert.deepEqual(rows.map(x => x[key]), patches.categoryIds, 'A2 outfit inverse rejects changed ID order or missing/duplicate IDs');
  const matches = A2_OUTFIT_REVIEW.rows.map(r => {
    const index = rows.findIndex(x => x[key] === r.id), value = rows[index];
    const state = isDeepStrictEqual(value, r[afterKey]) ? 'after' : isDeepStrictEqual(value, r[beforeKey]) ? 'before' : 'unknown';
    assert.notEqual(state, 'unknown', 'A2 outfit inverse rejects changed text, aliases or metadata: ' + r.id);
    return { index, state, r };
  });
  assert.equal(new Set(matches.map(x => x.state)).size, 1, 'A2 outfit inverse rejects mixed migration states');
  for (const { index, r } of matches) rows[index] = structuredClone(r[beforeKey]);
  return matches[0].state;
}
export function preA2OutfitDatabase(database) {
  const copy = preA2SpecialTapeDatabase(database);
  inverse(copy.Wardrobe[A2_OUTFIT_REVIEW.category], 'stableId', 'generatedBefore', 'generatedAfter');
  return copy;
}
export function preA2OutfitProgramSources(sources, state) {
  assert.ok(['before', 'after'].includes(state));
  if (state === 'after') {
    try { sources = preA2SpecialTapeManagementSources(sources); }
    catch (error) { throw new Error('A2 outfit inverse rejects special-tape management: ' + error.message, { cause: error }); }
  }
  const restored = { ...sources };
  for (const [path, hashes] of Object.entries(patches.hashes)) {
    assert.equal(typeof sources[path], 'string', 'A2 outfit inverse missing program source: ' + path);
    const accepted = [hashes[state], ...(state === 'before' ? hashes.earlierBefore || [] : [])];
    assert.ok(accepted.includes(hash(sources[path])), 'A2 outfit inverse rejects unreviewed or mixed program source: ' + path);
  }
  for (const [path, expected] of Object.entries(patches.newFiles)) {
    if (state === 'after' || sources[path] !== undefined) assert.equal(hash(sources[path] || ''), expected, 'A2 outfit inverse rejects missing or changed new helper');
    delete restored[path];
  }
  if (state === 'after') {
    for (const p of patches.patches) {
      assert.equal(restored[p.path].split(p.after).length - 1, 1, 'A2 outfit inverse requires exact insertion');
      restored[p.path] = restored[p.path].replace(p.after, p.before);
    }
    for (const file of patches.management) {
      const value = JSON.parse(restored[file.path]);
      for (const change of file.changes) {
        const keys = [...change.keys], last = keys.pop();
        const parent = keys.reduce((x, key) => x[key], value);
        assert.deepEqual(parent[last], change.after);
        if (change.beforePresent) parent[last] = change.before;
        else delete parent[last];
      }
      restored[file.path] = JSON.stringify(value, null, 2) + '\n';
    }
    for (const [path, hashes] of Object.entries(patches.hashes)) assert.equal(hash(restored[path]), hashes.before, 'A2 outfit inverse must exactly restore base: ' + path);
  }
  return restored;
}
export function restorePreA2OutfitFiles(directory) {
  assert.notEqual(realpathSync(directory), realpathSync(A2_OUTFIT_ROOT), 'A2 outfit inverse only writes an isolated copy');
  restorePreA2SpecialTapeFiles(directory);
  const categoryFile = join(directory, A2_OUTFIT_REVIEW.sourceFile);
  const category = JSON.parse(readFileSync(categoryFile));
  const state = inverse(category.entries, 'id', 'before', 'after');
  const databaseFile = join(directory, 'webapp/src/data/database.json');
  const database = JSON.parse(readFileSync(databaseFile));
  const dbState = inverse(database.Wardrobe[A2_OUTFIT_REVIEW.category], 'stableId', 'generatedBefore', 'generatedAfter');
  assert.equal(state, dbState, 'A2 outfit inverse requires matching source and generated states');
  const markdownFile = join(directory, 'knowledge_base/wardrobe_and_styling.md');
  let markdown = readFileSync(markdownFile, 'utf8');
  for (const row of A2_OUTFIT_REVIEW.rows) {
    const from = '| `' + row[state].en + '` |';
    assert.equal(markdown.split(from).length - 1, 1, 'A2 outfit inverse Markdown must agree: ' + row.id);
    if (state === 'after') markdown = markdown.replace(from, '| `' + row.before.en + '` |');
  }
  const sources = Object.fromEntries([...Object.keys(patches.hashes), ...Object.keys(patches.newFiles)]
    .filter(path => existsSync(join(directory, path))).map(path => [path, readFileSync(join(directory, path), 'utf8')]));
  const restored = preA2OutfitProgramSources(sources, state);
  // All source, generated, Markdown and program checks succeeded before the first write.
  writeFileSync(categoryFile, JSON.stringify(category, null, 2) + '\n');
  writeFileSync(databaseFile, JSON.stringify(database, null, 2) + '\n');
  writeFileSync(markdownFile, markdown);
  for (const [path, text] of Object.entries(restored)) writeFileSync(join(directory, path), text);
  for (const path of Object.keys(patches.newFiles)) rmSync(join(directory, path), { force: true });
}
export function openPreA2OutfitReplayRoot() {
  const directory = mkdtempSync(join(tmpdir(), 'vps-a2-outfits-history-'));
  try {
    mkdirSync(join(directory, 'webapp'));
    for (const path of ['webapp/src', 'scripts', 'knowledge_base']) cpSync(join(A2_OUTFIT_ROOT, path), join(directory, path), { recursive: true });
    for (const file of ['package.json', 'package-lock.json']) cpSync(join(A2_OUTFIT_ROOT, 'webapp', file), join(directory, 'webapp', file));
    symlinkSync(join(A2_OUTFIT_ROOT, 'webapp/node_modules'), join(directory, 'webapp/node_modules'), 'dir');
    restorePreA2WardrobeRecoveryFiles(directory);
    restorePreA2OutfitFiles(directory);
    return { directory, cleanup: () => rmSync(directory, { recursive: true, force: true }) };
  } catch (error) { rmSync(directory, { recursive: true, force: true }); throw error; }
}

import { restorePreA2SpecialTapeDatabaseFile, restorePreA2SpecialTapeReplayFiles } from './a2SpecialTapeReplay.mjs';
import { restorePreA2MarkdownSnapshotFiles } from './a2MarkdownSnapshotReplay.mjs';
// Restore only the reviewed parser delta in an isolated copy. Historical seals stay immutable.
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, existsSync, realpathSync, rmSync, cpSync, mkdirSync, mkdtempSync, symlinkSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
export const RECOVERY_ROOT = fileURLToPath(new URL('../../', import.meta.url));
export const RECOVERY_PATCHES = JSON.parse(readFileSync(new URL('./a2WardrobeColorRecoveryPatches.json', import.meta.url)));
const hash = text => createHash('sha256').update(text).digest('hex');
export function restorePreA2WardrobeRecoveryFiles(directory) {
  assert.notEqual(realpathSync(directory),realpathSync(RECOVERY_ROOT),'Recovery inverse must use an isolated copy');
  const prepared = [];
  const states = [];
  for (const entry of RECOVERY_PATCHES.files) {
    const text = readFileSync(join(directory,entry.path),'utf8');
    const state = hash(text) === entry.afterHash ? 'after' : hash(text) === entry.beforeHash ? 'before' : 'unknown';
    assert.notEqual(state,'unknown','Recovery inverse rejects unreviewed source: '+entry.path);
    states.push(state);
    let before = text;
    if(state === 'after') for(const patch of entry.patches){
      assert.equal(before.split(patch.after).length-1,1,'Recovery inverse requires exact insertion');
      before=before.replace(patch.after,patch.before);
    }
    assert.equal(hash(before),entry.beforeHash,'Recovery inverse must restore exact base');
    prepared.push([entry.path,before]);
  }
  assert.equal(new Set(states).size,1,'Recovery inverse rejects mixed source states');
  const state=states[0];
  for(const [path,sha] of Object.entries(RECOVERY_PATCHES.newFiles)){
    if(state==='after'||existsSync(join(directory,path)))assert.equal(hash(readFileSync(join(directory,path))),sha,'Recovery inverse rejects changed helper');
  }
  // No writes until every input passed. Idempotent historical roots are valid.
  if(state==='after') for(const [path,text] of prepared)writeFileSync(join(directory,path),text);
  for(const path of Object.keys(RECOVERY_PATCHES.newFiles))rmSync(join(directory,path),{force:true});
}

export async function withPreA2WardrobeRecoveryReplay(run) {
  const directory=mkdtempSync(join(tmpdir(),'vps-a2-recovery-test-'));
  try {
    mkdirSync(join(directory,'webapp'));
    cpSync(join(RECOVERY_ROOT,'webapp/src'),join(directory,'webapp/src'),{recursive:true});
    cpSync(join(RECOVERY_ROOT,'webapp/package.json'),join(directory,'webapp/package.json'));
    symlinkSync(join(RECOVERY_ROOT,'webapp/node_modules'),join(directory,'webapp/node_modules'),'dir');
    cpSync(join(RECOVERY_ROOT,'scripts/lib'),join(directory,'scripts/lib'),{recursive:true});
    restorePreA2SpecialTapeDatabaseFile(directory);
    restorePreA2SpecialTapeReplayFiles(directory);
    restorePreA2MarkdownSnapshotFiles(directory);
    restorePreA2WardrobeRecoveryFiles(directory);
    return await run(directory);
  } finally { rmSync(directory,{recursive:true,force:true}); }
}

