function filterControlsByKeys(controls, keys) {
  const keySet = new Set(keys);
  return controls.filter((control) => keySet.has(control.key));
}

function countEffectiveSelections(sectionId, locks, controls) {
  return Array.from(new Set(getSectionKeys(sectionId)))
    .filter((key) => locks.subjectCount !== '2' || !['character', 'wardrobe'].includes(sectionId) || getDuoFieldRole(key))
    .filter((key) => getControlOptionLabel(controls, key, locks[key]))
    .length;
}

function formatSelectionStatus(count) {
  return count > 0 ? `已選 ${count}` : '未設定';
}

function areLocksEqual(left, right) {
  const keys = new Set([...Object.keys(left || {}), ...Object.keys(right || {})]);
  return Array.from(keys).every((key) => JSON.stringify(left?.[key]) === JSON.stringify(right?.[key]));
}

function formatSectionStatus(sectionId, count, isCleared) {
  if (!isCleared) return formatSelectionStatus(count);
  if (sectionId === 'character') return '保留必要預設';
  if (sectionId === 'scene') return '隨機／保留預設';
  if (sectionId === 'photography') return '保留預設';
  return '隨機';
}

function findControlOption(control, value) {
  if (!value) return null;
  return control?.options?.find((option) => option.id === value) || null;
}

function getSelectedPromptText(control, value) {
  const selectedOption = findControlOption(control, value);
  if (!selectedOption || selectedOption.zh === '全無') return '';
  return selectedOption.en || '';
}

function getOptionSwatches(option) {
  const colorPairs = [option?.topColor, option?.bottomColor]
    .filter(Boolean)
    .map((color) => {
      const hex = color.hex || (color.en || '').match(/#[0-9a-fA-F]{6}/)?.[0] || NAMED_COLOR_SWATCHES[color.en]?.[0] || '';
      return hex ? { color: hex, label: color.zh } : null;
    })
    .filter(Boolean);
  if (colorPairs.length > 0) return colorPairs;

  const hexMatches = (option?.en || '').match(/#[0-9a-fA-F]{6}/g) || [];
  if (hexMatches.length > 0) {
    return Array.from(new Set(hexMatches)).slice(0, 3).map((color) => ({ color, label: color }));
  }

  const namedSwatches = NAMED_COLOR_SWATCHES[option?.en] || NAMED_COLOR_SWATCHES[option?.id];
  return (namedSwatches || []).slice(0, 3).map((color) => ({ color, label: option?.zh || color }));
}

function getSingleColorGroup(option) {
  const id = option?.id || '';
  if (['black', 'white', 'off-white', 'beige', 'dark-grey', 'light-grey', 'dark-brown', 'light-brown', 'brown'].includes(id)) return 'neutral';
  if (['red', 'bright-red', 'neon-red', 'pink', 'neon-pink', 'coral', 'orange', 'burgundy'].includes(id)) return 'red-pink';
  if (['goose-yellow', 'yellow', 'neon-yellow', 'green', 'light-green', 'dark-green', 'olive-green', 'neon-green', 'mint-green'].includes(id)) return 'yellow-green';
  if (['blue', 'light-blue', 'dark-blue', 'bright-blue', 'royal-blue', 'neon-blue', 'cyan', 'tiffany-aqua', 'turquoise-green', 'purple', 'lavender'].includes(id)) return 'blue-purple';
  if (['silver', 'mirror-chrome-silver', 'gold'].includes(id)) return 'metallic';
  if (['colorful', 'multicolor-horizontal-stripes'].includes(id)) return 'multicolor';
  return 'neutral';
}

function getSingleColorBackground(option, swatches) {
  const colors = swatches.map((swatch) => swatch.color);
  if (option?.id === 'multicolor-horizontal-stripes' && colors.length > 1) {
    return `linear-gradient(to bottom, ${colors[0]} 0 33.333%, ${colors[1]} 33.333% 66.666%, ${colors[2] || colors[0]} 66.666% 100%)`;
  }
  if (colors.length > 1) return `linear-gradient(135deg, ${colors.join(', ')})`;
  return colors[0] || 'transparent';
}

function getOptionCategory(option, control) {
  const label = option?.zh || '';
  if (control?.label?.includes('配色') || control?.label?.includes('色')) return '配色';
  if (label.includes('全無')) return '全無';
  if (control?.key === 'characterProfileId') return '角色卡';
  if (label.startsWith('套裝：')) return '套裝';
  if (label.startsWith('連身：')) return '連身';
  if (label.includes('配色') || option?.topColor || option?.bottomColor) return '配色';
  if (label.includes('特殊') || label.includes('風格') || label.includes('造型')) return '造型';
  return '選項';
}

function getReferenceImageUrl(option) {
  const referenceImage = option?.meta?.referenceImage;
  if (!referenceImage) return '';
  if (/^https?:\/\//.test(referenceImage) || referenceImage.startsWith('/')) return referenceImage;
  return `${import.meta.env.BASE_URL}${referenceImage}`;
}

function isWardrobeImagePickerOption(option, control) {
  const label = option?.zh || '';
  if (option?.zh === '全無' || option?.id === 'none' || option?.id === 'random' || option?.random) return true;
  if (WARDROBE_OUTFIT_PICKER_KEYS.has(control.key)) return label.startsWith('套裝：');
  if (WARDROBE_DRESS_PICKER_KEYS.has(control.key)) return label.startsWith('連身：');
  if (!getReferenceImageUrl(option)) return false;
  return true;
}

function WardrobePickerField({ control, value, disabled, onOpen, onChange, onCopy }) {
  const selectedOption = findControlOption(control, value);
  const selectedLabel = selectedOption?.zh || '隨機';
  const copyText = getSelectedPromptText(control, value);
  const swatches = getOptionSwatches(selectedOption);
  const isMuted = !selectedOption || selectedOption.zh === '全無';

  return (
    <label className={`field wardrobe-picker-field ${control.key.startsWith('completeLookPalette') ? 'wardrobe-complete-palette-field' : ''} ${disabled ? 'field-disabled' : ''}`}>
      <div className="field-heading-row">
        <span>{control.displayLabel || control.label}</span>
        <button
          type="button"
          className="icon-btn control-copy-icon-btn"
          disabled={disabled || !copyText}
          onClick={() => onCopy(copyText)}
          title={`Copy ${control.label} prompt`}
          aria-label={`Copy ${control.label} prompt`}
        >
          <Copy size={14} />
        </button>
      </div>
      <button
        type="button"
        aria-label={`${control.label}：${selectedLabel}`}
        className={`wardrobe-picker-trigger ${isMuted ? 'wardrobe-picker-trigger-muted' : ''}`}
        disabled={disabled}
        onClick={onOpen}
      >
        <span className="wardrobe-picker-trigger-main">{selectedLabel}</span>
        {swatches.length > 0 ? (
          <span className="wardrobe-picker-swatches" aria-hidden="true">
            {swatches.map((swatch) => (
              <span key={`${swatch.color}-${swatch.label}`} className="wardrobe-picker-swatch" style={{ background: swatch.color }} />
            ))}
          </span>
        ) : null}
        <span className="wardrobe-picker-open">選擇</span>
      </button>
      {value ? (
        <button className="wardrobe-picker-clear" type="button" disabled={disabled} onClick={() => onChange('')}>
          回到隨機
        </button>
      ) : null}
    </label>
  );
}

function WardrobePickerModal({ control, contextLabel, value, query, onQueryChange, onClose, onSelect }) {
  const [activeColorFilter, setActiveColorFilter] = useState('all');
  const selectedOption = findControlOption(control, value);
  const normalizedQuery = query.trim().toLowerCase();
  const imageOnly = WARDROBE_IMAGE_ONLY_PICKER_KEYS.has(control.key);
  const singleColorMode = WARDROBE_SINGLE_COLOR_PICKER_KEYS.has(control.key);
  const pairedColorMode = WARDROBE_PAIRED_COLOR_PICKER_KEYS.has(control.key);
  const baseOptions = imageOnly ? control.options.filter((option) => isWardrobeImagePickerOption(option, control)) : control.options;
  const noneOption = baseOptions.find((option) => option.id === 'none' || option.zh === '全無');
  const randomOption = pairedColorMode ? baseOptions.find((option) => option.random || option.id === 'random') : null;
  const visibleOptions = baseOptions.filter((option) => {
    if (option.meta?.outerwear?.retired) return false;
    if ((singleColorMode || pairedColorMode) && (option === noneOption || option === randomOption)) return false;
    if (singleColorMode && activeColorFilter !== 'all' && getSingleColorGroup(option) !== activeColorFilter) return false;
    if (!normalizedQuery) return true;
    const pairSearchText = [option.topColor?.zh, option.topColor?.en, option.bottomColor?.zh, option.bottomColor?.en].filter(Boolean).join(' ');
    return `${option.zh} ${option.en || ''} ${pairSearchText}`.toLowerCase().includes(normalizedQuery);
  });
  const hasReferenceImageOptions = visibleOptions.some((option) => getReferenceImageUrl(option));
  const categories = Array.from(new Set(baseOptions.map((option) => getOptionCategory(option, control))));
  const searchPlaceholder = singleColorMode || pairedColorMode
    ? '搜尋中文或英文顏色名稱'
    : imageOnly
      ? `搜尋${control.label}預覽圖或 prompt 關鍵字`
      : '搜尋套裝、連身、配色或 prompt 關鍵字';
  const modalClassName = [
    'modal-panel',
    'wardrobe-picker-modal',
    singleColorMode ? 'wardrobe-picker-modal--colors' : '',
    pairedColorMode ? 'wardrobe-picker-modal--paired-colors' : '',
  ].filter(Boolean).join(' ');

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className={modalClassName} role="dialog" aria-modal="true" aria-label={contextLabel || control.label}
        onClick={(event) => event.stopPropagation()}
        onKeyDown={(event) => {
          if (event.key === 'Escape') { event.stopPropagation(); onClose(); }
          if (event.key !== 'Tab') return;
          const focusable = [...event.currentTarget.querySelectorAll('button:not(:disabled), input:not(:disabled), select:not(:disabled), [tabindex="0"]')].filter(element => element.getClientRects().length);
          const first = focusable[0];
          const last = focusable[focusable.length - 1];
          if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
          if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
        }}>
        <div className="modal-header">
          <div>
            <div className="lock-title">{contextLabel || control.label}</div>
            {!singleColorMode && !pairedColorMode ? (
              <p className="lock-subtitle">搜尋中文名稱、英文 prompt 或配色關鍵字，適合資料庫持續增加時快速定位。</p>
            ) : null}
          </div>
          <button className="secondary" type="button" onClick={onClose}>關閉</button>
        </div>

        <div className="wardrobe-picker-toolbar">
          <input
            className="text-input wardrobe-picker-search"
            value={query}
            onChange={(event) => onQueryChange(event.target.value)}
            placeholder={searchPlaceholder}
            autoFocus
          />
        </div>

        {singleColorMode ? (
          <div className="wardrobe-picker-color-toolbar">
            <div className="wardrobe-picker-color-filters" role="group" aria-label="依色系篩選">
              {COLOR_FILTERS.map((filter) => (
                <button
                  key={filter.id}
                  className={`wardrobe-picker-filter${activeColorFilter === filter.id ? ' wardrobe-picker-filter-active' : ''}`}
                  type="button"
                  aria-pressed={activeColorFilter === filter.id}
                  onClick={() => setActiveColorFilter(filter.id)}
                >
                  {filter.label}
                </button>
              ))}
            </div>
            <span className="wardrobe-picker-count">{visibleOptions.length} 色票</span>
            {noneOption ? (
              <button
                className={`wardrobe-picker-color-action${selectedOption?.id === noneOption.id ? ' wardrobe-picker-color-action-active' : ''}`}
                type="button"
                aria-pressed={selectedOption?.id === noneOption.id}
                onClick={() => onSelect(noneOption.id)}
              >
                {selectedOption?.id === noneOption.id ? <Check size={14} aria-hidden="true" /> : null}
                全無
              </button>
            ) : null}
          </div>
        ) : pairedColorMode ? (
          <div className="wardrobe-picker-pair-toolbar">
            <div className="wardrobe-picker-color-actions" role="group" aria-label="配色狀態">
              {randomOption ? (
                <button
                  className={`wardrobe-picker-color-action${selectedOption?.id === randomOption.id ? ' wardrobe-picker-color-action-active' : ''}`}
                  type="button"
                  aria-pressed={selectedOption?.id === randomOption.id}
                  onClick={() => onSelect(randomOption.id)}
                >
                  {selectedOption?.id === randomOption.id ? <Check size={14} aria-hidden="true" /> : null}
                  隨機
                </button>
              ) : null}
              {noneOption ? (
                <button
                  className={`wardrobe-picker-color-action${selectedOption?.id === noneOption.id ? ' wardrobe-picker-color-action-active' : ''}`}
                  type="button"
                  aria-pressed={selectedOption?.id === noneOption.id}
                  onClick={() => onSelect(noneOption.id)}
                >
                  {selectedOption?.id === noneOption.id ? <Check size={14} aria-hidden="true" /> : null}
                  全無
                </button>
              ) : null}
            </div>
            <span className="wardrobe-picker-count">{visibleOptions.length} 組配色</span>
          </div>
        ) : (
          <div className="wardrobe-picker-category-row">
            {categories.map((category) => (
              <span key={category} className="wardrobe-picker-category">{category}</span>
            ))}
            <span className="wardrobe-picker-count">{visibleOptions.length} options</span>
          </div>
        )}

        <div className={`wardrobe-picker-option-grid ${hasReferenceImageOptions ? 'wardrobe-picker-option-grid-image' : ''} ${singleColorMode ? 'wardrobe-picker-color-grid' : ''} ${pairedColorMode ? 'wardrobe-picker-pair-grid' : ''}`}>
          {visibleOptions.map((option) => {
            const swatches = getOptionSwatches(option);
            const isActive = selectedOption?.id === option.id;
            if (singleColorMode) {
              return (
                <button
                  key={option.id}
                  type="button"
                  className={`wardrobe-picker-color-swatch${isActive ? ' wardrobe-picker-color-swatch-active' : ''}`}
                  aria-label={`${option.zh} (${option.en || ''})`}
                  aria-pressed={isActive}
                  title={`${option.zh} · ${option.en || ''}`}
                  disabled={option.disabled}
                  onClick={() => onSelect(option.id)}
                >
                  <span className={`wardrobe-picker-color-tile${option.id === 'multicolor-horizontal-stripes' ? ' wardrobe-picker-color-tile-striped' : ''}`} style={{ background: getSingleColorBackground(option, swatches) }} />
                  {isActive ? <Check className="wardrobe-picker-color-check" size={18} aria-hidden="true" /> : null}
                </button>
              );
            }
            if (pairedColorMode && option.topColor && option.bottomColor) {
              const [topSwatch, bottomSwatch] = swatches;
              return (
                <button
                  key={option.id}
                  type="button"
                  className={`wardrobe-picker-pair-option${isActive ? ' wardrobe-picker-pair-option-active' : ''}`}
                  aria-label="特殊上下身配色：上身色塊在上方，下身色塊在下方"
                  aria-pressed={isActive}
                  disabled={option.disabled}
                  onClick={() => onSelect(option.id)}
                >
                  <span className="wardrobe-picker-pair-color">
                    <span className="wardrobe-picker-pair-label">上身</span>
                    <span className="wardrobe-picker-pair-swatch" style={{ background: topSwatch?.color || 'transparent' }} />
                  </span>
                  <span className="wardrobe-picker-pair-color">
                    <span className="wardrobe-picker-pair-label">下身</span>
                    <span className="wardrobe-picker-pair-swatch" style={{ background: bottomSwatch?.color || 'transparent' }} />
                  </span>
                  {isActive ? <Check className="wardrobe-picker-pair-check" size={16} aria-hidden="true" /> : null}
                </button>
              );
            }
            const isColorOption = swatches.length > 0;
            const isNoneOption = option.zh === '全無' || option.id === 'none';
            const isRandomOption = Boolean(option.random) || option.id === 'random';
            const referenceImageUrl = getReferenceImageUrl(option);
            const hasReferenceImage = Boolean(referenceImageUrl);
            const useColorCardStyle = isColorOption || isNoneOption || isRandomOption;
            return (
              <button
                key={option.id}
                type="button"
                className={`wardrobe-picker-option ${useColorCardStyle ? 'wardrobe-picker-option-color' : ''} ${hasReferenceImage ? 'wardrobe-picker-option-image' : ''} ${isNoneOption ? 'wardrobe-picker-option-none' : ''} ${isActive ? 'wardrobe-picker-option-active' : ''}`}
                disabled={option.disabled}
                onClick={() => onSelect(option.id)}
              >
                {hasReferenceImage ? (
                  <span className="wardrobe-picker-option-image-frame" aria-hidden="true">
                    <img src={referenceImageUrl} alt="" loading="lazy" decoding="async" />
                  </span>
                ) : null}
                <span className="wardrobe-picker-option-topline">
                  <strong>{useColorCardStyle ? (option.en || option.zh) : option.zh}</strong>
                  {!useColorCardStyle ? <span>{getOptionCategory(option, control)}</span> : null}
                </span>
                {swatches.length > 0 ? (
                  <span className="wardrobe-picker-swatches wardrobe-picker-option-swatches" aria-hidden="true">
                    {swatches.map((swatch) => (
                      <span key={`${option.id}-${swatch.color}-${swatch.label}`} className="wardrobe-picker-swatch" style={{ background: swatch.color }} />
                    ))}
                  </span>
                ) : null}
                {option.en && !useColorCardStyle && !hasReferenceImage ? <span className="wardrobe-picker-option-copy">{option.en}</span> : null}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

