export function buildMarkdownExport(data) {
  const labels = {
    midjourney: data.promptLabels?.midjourney || 'AI Prompt',
    grok: data.promptLabels?.grok || 'Gpt',
    zImage: normalizeZImageDisplayLabel(data.promptLabels?.zImage, 'Z-Image'),
  };
  const structured = data.structured && typeof data.structured === 'object' ? data.structured : {};
  const extraPromptEntries = Array.isArray(data.extraPrompts)
    ? data.extraPrompts.map((entry) => ({ label: entry.label, text: entry.text }))
    : [];
  const promptEntries = [
    { label: labels.midjourney, text: data.midjourneyPrompt },
    { label: labels.grok, text: data.grokPrompt },
    { label: labels.zImage, text: data.zImagePrompt },
    ...(data.nanoBananaPrompt?.trim() ? [{ label: 'Nano Banana 2.1', text: data.nanoBananaPrompt }] : []),
    ...extraPromptEntries,
  ].filter((entry) => entry.text);

  // Empty visual content cannot encode its silence choice in the prose itself.
  const silenceLocks = Object.fromEntries(getLockControls().filter((control) => (
    OPTIONAL_SILENCE_LOCK_PATTERN.test(control.key)
    && control.options?.some((option) => option.id === data.selection?.[control.key] && option.zh === '全無')
  )).map((control) => [control.key, data.selection[control.key]]));
  const silenceMetadata = Object.keys(silenceLocks).length
    ? `<!-- VPStudio Optional Silence: ${JSON.stringify(silenceLocks)} -->\n` : '';

  const captureMetadata = data.selection?.captureMode === 'observation'
    ? `<!-- VPStudio Observation Capture: ${JSON.stringify(data.selection).replace(/</g, '\\u003c').replace(/>/g, '\\u003e')} -->\n` : '';

  return `${encodePage1MarkdownSnapshot(data)}${silenceMetadata}${captureMetadata}# Generated Prompt - ${new Date(data.date).toLocaleString()}
**Source:** ${data.sourceLabel || 'Prompt 工作台'}
**Summary:** ${data.summary}

${promptEntries.map((entry) => `## ${entry.label}
\`\`\`text
${entry.text}
\`\`\``).join('\n\n')}

---

## Structured Scheme
${Object.entries(structured)
  .map(([key, items]) => {
    const text = items.map((item) => `${item.en} (${item.zh})`).join(', ');
    return `* **${key}:** ${text || '-'}`;
  })
  .join('\n')}
`;
}

