    source: String(data?.source || 'page1'),
    sourceLabel: String(data?.sourceLabel || 'Prompt 工作台'),
    summary: String(data?.summary || ''),
    summaryFields: normalizeManifestSummaryFields(data),
    tags: collectSourceTags(data),
