export function getControlOptionLabel(controls, key, value) {
  if (!value) return '';
  const control = controls.find((item) => item.key === key);
  const option = control?.options?.find((item) => item.id === value);
  if (!option || option.zh === '全無' || option.zh === '隨機' || option.en === 'none') return '';
  return getCameraControlDisplayLabel(key, option);
}

function buildSummaryText(parts) {
  const filtered = parts.filter(Boolean);
  return filtered.length > 0 ? filtered.join(' / ') : '尚未形成明確選項';
}

function isFixedCompositionSetActive(locks, controls) {
  return Boolean(getControlOptionLabel(controls, 'fixedCompositionSetId', locks.fixedCompositionSetId));
}

function isOutfitPresetActive(locks, controls, key) {
  return Boolean(getControlOptionLabel(controls, key, locks[key]));
}

function isCoveredByOutfitPreset(key, activePresets) {
  return (
    (activePresets.single && OUTFIT_PRESET_COVERED_KEYS.has(key))
    || (activePresets.dress && DRESS_COVERED_KEYS.has(key))
    || (activePresets.a && OUTFIT_PRESET_A_COVERED_KEYS.has(key))
    || (activePresets.b && OUTFIT_PRESET_B_COVERED_KEYS.has(key))
  );
}

function getEffectiveWardrobeOptionLabel(controls, locks, key, activePresets) {
  const riseControl = key.match(/^bottomRise([AB]?)Id$/);
  if (riseControl) {
    const { pants, rise } = bottomRiseControlContext(controls, locks, riseControl[1]);
    if (bottomRiseConflict(pants, rise)) return '';
  }
  const topControl = key.match(/^top(?:Fit|Styling)([AB]?)Id$/);
  if (topControl) {
    const { top, fit } = underbustTopControlContext(controls, locks, topControl[1]);
    if (isUnderbustTopFit(fit)) {
      if (key.startsWith('topFit') && underbustTopConflict(top)) return '';
      const styling = controls.find(c => c.key === key)?.options.find(o => o.id === locks[key]);
      if (!underbustTopConflict(top) && key.startsWith('topStyling') && isUnderbustIncompatibleStyle(styling)) return '';
    }
  }
  const styling = key.match(/^outerwear([AB]?)StylingId$/);
  if (styling) {
    const item = controls.find(c => c.key === key)?.options.find(o => o.id === locks[key]);
    const fullyClosed = isFullyClosedOpening(locks[`outerwear${styling[1]}OpeningId`]);
    if (fullyClosed && !outerwearStylingAllowsClosed(item)) return '';
    if (isNewOuterwearStyling(item) && outerwearStylingConflict(item, { ...outerwearStylingControlContext(controls, locks, styling[1]), fullyClosed })) return '';
  }
  if (isCoveredByOutfitPreset(key, activePresets)) return '';
  return getControlOptionLabel(controls, key, locks[key]);
}

function buildWardrobeAccessoryLabels(keys, controls, locks, activeOutfitPresets) {
  return buildAccessorySummaryEntries(
    keys.map((key) => ({
      key,
      text: getEffectiveWardrobeOptionLabel(controls, locks, key, activeOutfitPresets),
    }))
  ).map((entry) => entry.text);
}

function getActiveOutfitPresets(locks, controls) {
  return {
    single: isOutfitPresetActive(locks, controls, 'outfitPresetId'),
    dress: isOutfitPresetActive(locks, controls, 'dressId'),
    a: isOutfitPresetActive(locks, controls, 'outfitPresetAId'),
    b: isOutfitPresetActive(locks, controls, 'outfitPresetBId'),
  };
}

export function normalizeCharacterCardLayerIds(layerIds) {
  if (!Array.isArray(layerIds)) return [];
  const selectedLayers = new Set(layerIds);
  return CHARACTER_CARD_LAYER_KEYS.filter((key) => selectedLayers.has(key));
}

export function buildWorkspaceSummary(locks, controls, { groupDuo = true } = {}) {
  const person = activeImportedPerson(locks);
  const importedSummary = person ? buildWorkspaceSummary(importedPersonLocks(person), controls) : null;
  const specialSubjectControl = controls.find((control) => control.key === 'specialSubjectId');
  const specialSubjectOption = specialSubjectControl?.options?.find((option) => option.id === locks.specialSubjectId);
  const characterProfileControl = controls.find((control) => control.key === 'characterProfileId');
  const characterProfileOption = characterProfileControl?.options?.find((option) => option.id === locks.characterProfileId);
  const isSpecialSubjectMode = Boolean(specialSubjectOption?.specialSubject);
  const isCharacterProfileMode = Boolean(characterProfileOption?.specialSubject);
  const activeOutfitPresets = getActiveOutfitPresets(locks, controls);
  const wardrobeLabel = (key) => getEffectiveWardrobeOptionLabel(controls, locks, key, activeOutfitPresets);
  const singleAccessoryLabels = buildWardrobeAccessoryLabels(
    SINGLE_ACCESSORY_SUMMARY_KEYS,
    controls,
    locks,
    activeOutfitPresets,
  );
  const automaticGarterBeltLabels = [];
  if (!isSpecialSubjectMode && !isCharacterProfileMode) {
    const sharedSpecialOutfitActive = Boolean(wardrobeLabel('specialOutfitId'));
    if (!sharedSpecialOutfitActive) {
      if (hasConditionalGarterBeltLabels(
        wardrobeLabel('pantsId'),
        wardrobeLabel('legwearId'),
      )) {
        automaticGarterBeltLabels.push(CONDITIONAL_GARTER_BELT_SUMMARY_LABEL);
      }

      if (locks.subjectCount === '2') {
        for (const [suffix, roleLabel] of [['A', '人物 1'], ['B', '人物 2']]) {
          if (wardrobeLabel(`specialOutfit${suffix}Id`)) continue;
          if (hasConditionalGarterBeltLabels(
            wardrobeLabel(`pants${suffix}Id`),
            wardrobeLabel(`legwear${suffix}Id`),
          )) {
            automaticGarterBeltLabels.push(`${roleLabel}：${CONDITIONAL_GARTER_BELT_SUMMARY_LABEL}`);
          }
        }
      }
    }
  }
  const importedCharacterCardWardrobe = isCharacterProfileMode && !isSpecialSubjectMode
    ? normalizeCharacterCardLayerIds(locks.characterCardWardrobeLayerIds).map((key) => `角色卡${CHARACTER_CARD_LAYER_LABELS[key]}`)
    : [];

  const characterSummary = isSpecialSubjectMode
    ? specialSubjectOption?.zh || '特殊角色'
    : isCharacterProfileMode
      ? characterProfileOption?.zh || '角色卡'
      : buildSummaryText([
        getControlOptionLabel(controls, 'bodyTypeId', locks.bodyTypeId),
        getControlOptionLabel(controls, 'bodyTypeAId', locks.bodyTypeAId),
        getControlOptionLabel(controls, 'bodyTypeBId', locks.bodyTypeBId),
        getControlOptionLabel(controls, 'facialFeaturesId', locks.facialFeaturesId),
        getControlOptionLabel(controls, 'facialFeaturesAId', locks.facialFeaturesAId),
        getControlOptionLabel(controls, 'facialFeaturesBId', locks.facialFeaturesBId),
        getControlOptionLabel(controls, 'skinDetailsId', locks.skinDetailsId),
        getControlOptionLabel(controls, 'skinDetailsAId', locks.skinDetailsAId),
        getControlOptionLabel(controls, 'skinDetailsBId', locks.skinDetailsBId),
        getControlOptionLabel(controls, 'hairstyleId', locks.hairstyleId),
        getControlOptionLabel(controls, 'hairstyleAId', locks.hairstyleAId),
        getControlOptionLabel(controls, 'hairstyleBId', locks.hairstyleBId),
        getControlOptionLabel(controls, 'hairStylingStateId', locks.hairStylingStateId),
        getControlOptionLabel(controls, 'hairStylingStateAId', locks.hairStylingStateAId),
        getControlOptionLabel(controls, 'hairStylingStateBId', locks.hairStylingStateBId),
        getControlOptionLabel(controls, 'hairColorId', locks.hairColorId),
        getControlOptionLabel(controls, 'hairColorAId', locks.hairColorAId),
        getControlOptionLabel(controls, 'hairColorBId', locks.hairColorBId),
  ]);
  const specifiedAction = getSpecifiedAction(locks, { cameraControls: controls });
